import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class RestrictByOneTypeOfResultVisitor_caseObjectType_TriageGen1Test {

    private com.google.javascript.jscomp.type.ChainableReverseAbstractInterpreter.RestrictByOneTypeOfResultVisitor visitor;
    private ObjectType mockObjectType;
    private JSType mockJSType;

    @Before
    public void setUp() throws Exception {
        visitor = new com.google.javascript.jscomp.type.ChainableReverseAbstractInterpreter.RestrictByOneTypeOfResultVisitor();
        mockObjectType = mock(ObjectType.class);
        mockJSType = mock(JSType.class);

        // Using reflection to set private fields if necessary, 
        // assuming 'value' and 'resultEqualsValue' are fields in the visitor class.
        // Since the provided snippet uses them, they must be accessible or set via reflection.
    }

    private void setFieldValue(String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = visitor.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(visitor, value);
    }

    @Test
    public void testCaseObjectType_valueIsFunction_resultEqualsValueTrue_ctorIsSubtype() throws Exception {
        setFieldValue("value", "function");
        setFieldValue("resultEqualsValue", true);

        JSType ctorType = mock(JSType.class);
        // Mocking getNativeType behavior via spy or assuming it's accessible/overridable
        // Since we can't easily mock protected/internal methods of the class under test without a spy:
        com.google.javascript.jscomp.type.ChainableReverseAbstractInterpreter.RestrictByOneTypeOfResultVisitor spyVisitor = 
            org.mockito.Mockito.spy(visitor);

        when(spyVisitor.getNativeType(org.mockito.ArgumentMatchers.any())).thenReturn(ctorType);
        when(ctorType.isSubtype(mockObjectType)).thenReturn(true);

        JSType result = spyVisitor.caseObjectType(mockObjectType);

        assertThat(result).isEqualTo(ctorType);
    }

    @Test
    public void testCaseObjectType_valueIsFunction_resultEqualsValueTrue_ctorIsNotSubtype() throws Exception {
        setFieldValue("value", "function");
        setFieldValue("resultEqualsValue", true);

        JSType ctorType = mock(JSType.class);
        com.google.javascript.jscomp.type.ChainableReverseAbstractInterpreter.RestrictByOneTypeOfResultVisitor spyVisitor = 
            org.mockito.Mockito.spy(visitor);

        when(spyVisitor.getNativeType(org.mockito.ArgumentMatchers.any())).thenReturn(ctorType);
        when(ctorType.isSubtype(mockObjectType)).thenReturn(false);

        JSType result = spyVisitor.caseObjectType(mockObjectType);

        assertThat(result).isNull();
    }

    @Test
    public void testCaseObjectType_valueIsFunction_resultEqualsValueFalse() throws Exception {
        setFieldValue("value", "function");
        setFieldValue("resultEqualsValue", false);

        com.google.javascript.jscomp.type.ChainableReverseAbstractInterpreter.RestrictByOneTypeOfResultVisitor spyVisitor = 
            org.mockito.Mockito.spy(visitor);

        // Even if ctorType is a subtype, resultEqualsValue is false, so it should return null
        JSType ctorType = mock(JSType.class);
        when(spyVisitor.getNativeType(org.mockito.ArgumentMatchers.any())).thenReturn(ctorType);

        JSType result = spyVisitor.caseObjectType(mockObjectType);

        assertThat(result).isNull();
    }

    @Test
    public void testCaseObjectType_valueIsNotFunction_matchesExpectationTrue() throws Exception {
        setFieldValue("value", "not-function");

        com.google.javascript.jscomp.type.ChainableReverseAbstractInterpreter.RestrictByOneTypeOfResultVisitor spyVisitor = 
            org.mockito.Mockito.spy(visitor);
        when(spyVisitor.matchesExpectation("object")).thenReturn(true);

        JSType result = spyVisitor.caseObjectType(mockObjectType);

        assertThat(result).isEqualTo(mockObjectType);
    }

    @Test
    public void testCaseObjectType_valueIsNotFunction_matchesExpectationFalse() throws Exception {
        setFieldValue("value", "not-function");

        com.google.javascript.jscomp.type.ChainableReverseAbstractInterpreter.RestrictByOneTypeOfResultVisitor spyVisitor = 
            org.mockito.Mockito.spy(visitor);
        when(spyVisitor.matchesExpectation("object")).thenReturn(false);

        JSType result = spyVisitor.caseObjectType(mockObjectType);

        assertThat(result).isNull();
    }
}
